4	import com.loja.checkout.dto.CheckoutResponse;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.model.*;
7	import org.springframework.stereotype.Service;
8	
9	import java.math.BigDecimal;
10	import java.math.RoundingMode;
11	import java.util.List;
12	import java.util.Optional;
13	
14	@Service
15	public class CheckoutService {
16	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
17	    private static final int SCALE = 2;
18	
19	    public CheckoutResponse calcular(CheckoutRequest request) {
20	        try {
21	            return validarECalcular(request);
22	        } catch (ValidationException e) {
23	            return CheckoutResponse.error(e.getErrorCode());
24	        }
25	    }
26	
27	    private CheckoutResponse validarECalcular(CheckoutRequest request) {
28	        // 1. VALIDAÇÃO: Carrinho válido
29	        validarPedido(request);
30	
31	        // 2. VALIDAÇÃO: Nível do clube
32	        NivelClube nivelClube = validarNivelClube(request.nivelClube());
33	
34	        // 3. VALIDAÇÃO: Região
35	        Regiao regiao = validarRegiao(request.regiao());
36	
37	        // 4. VALIDAÇÃO: Modalidade entrega
38	        ModalidadeEntrega modalidade = validarModalidade(request.modalidadeEntrega());
39	
40	        // Calcular peso total
41	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
42	
43	        // 5. VALIDAÇÃO: Modalidade disponível para este pedido
44	        validarDisponibilidade(modalidade, pesoTotal);
45	
46	        // 6. VALIDAÇÃO: Cupom válido
47	        Optional<Cupom> cupom = Optional.empty();
48	        if (request.cupom() != null && !request.cupom().isEmpty()) {
49	            cupom = validarCupom(request.cupom());
50	        }
51	
52	        // 7. VALIDAÇÃO: Cupom aplicável
53	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request.itens());
54	        validarAplicabilidadeCupom(cupom, subtotalProdutos);
55	
56	        // 8. VALIDAÇÃO: Forma de pagamento
57	        FormaPagamento formaPagamento = validarFormaPagamento(request.formaPagamento());
58	
59	        // 9. VALIDAÇÃO: Parcelas válida
60	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
61	        validarParcelas(formaPagamento, parcelas);
62	
63	        // CÁLCULO DOS VALORES
64	        BigDecimal descontoCupom = calcularDescontoCupom(cupom, subtotalProdutos, request);
65	        BigDecimal frete = calcularFrete(modalidade, pesoTotal, nivelClube);
66	        int prazoEntrega = modalidade.getPrazoDias();
67	        BigDecimal seguro = calcularSeguro(regiao, subtotalProdutos);
68	
69	        // Subtotal: produtos - desconto + frete + seguro
70	        BigDecimal totalAntesAjuste = subtotalProdutos
71	                .subtract(descontoCupom)
72	                .add(frete)
73	                .add(seguro);
74	
75	        // 10. VALIDAÇÃO: Forma de pagamento disponível
76	        validarDisponibilidadeFormaPagamento(formaPagamento, totalAntesAjuste);
77	
78	        // Ajuste de pagamento
79	        BigDecimal ajustePagamento = calcularAjustePagamento(formaPagamento, totalAntesAjuste, parcelas);
80	        BigDecimal totalFinal = totalAntesAjuste.add(ajustePagamento);
